function clockDate(){const base=new Date(new Date().toISOString().slice(0,10)+'T12:00:00Z');base.setUTCDate(base.getUTCDate()+universeSession.clockOffset);return base.toISOString().slice(0,10)}
// Cache the calculated sky, not the natal comparison: editing a natal chart must take effect immediately.
let clockSkyCache=null;
