function livingBridge(){const friend=friendSamples[universeSession.friend];return uPage(`${uHead('THE CONSTELLATION BRIDGE · FREE COMMUNITY PREVIEW','Different worlds.<br><em>A shared possibility.</em>','Explore fictional friend galaxies, celebrate example milestones, and choose exactly what a visitor could see. Nothing is sent to a network.')}<div class="u-friend-picker" role="group" aria-label="Choose a fictional friend">${friendSamples.map((f,i)=>`<button data-u-friend="${i}" aria-pressed="${i===universeSession.friend}"><span class="u-avatar ${f.color}" aria-hidden="true"></span><strong>${f.name}</strong><small>Fictional profile · ${f.tier}</small></button>`).join('')}</div><div class="u-bridge-layout"><section class="u-friend-galaxy" data-palette="${friend.color}"><span class="eyebrow">${friend.name.toUpperCase()}’S GALAXY · FICTIONAL EXAMPLE</span><div class="u-friend-avatar" aria-hidden="true"></div><h2>${friend.title}.</h2><p>${friend.description}</p><div class="u-shared-placements"><span>Sun ${friend.sun}</span><span>Moon ${friend.moon}</span><span>Life Path ${friend.number}</span></div><small>Example fields this fictional person chose to share. Not calculated.</small></section><section class="u-glass u-friend-activity"><span class="eyebrow">SHARED MILESTONES · EXAMPLES</span><h2>A little courage<br><em>worth celebrating.</em></h2>${friend.milestones.map((m,i)=>{let key=`${universeSession.friend}-${i}`,on=universe.celebrations.includes(key);return `<div class="u-achievement"><span>✧</span><div><strong>${m}</strong><small>${friend.name} · fictional accomplishment</small></div><button data-u-celebrate="${key}" aria-pressed="${on}">${on?'Celebrated locally ✓':'Celebrate example'}</button></div>`}).join('')}<p class="u-fine">Celebrations are saved locally only. No real person is notified.</p><div class="u-actions">${uRoute('Explore relationship patterns','relationships')}${uRoute('Try a shared growth path','journey',friend.path)}</div></section></div><section class="u-glass u-sharing"><div><span class="eyebrow">YOUR SHARING CHOICES · PRIVATE BY DEFAULT</span><h2>Your universe.<br><em>Your permission.</em></h2><label class="u-check"><input type="checkbox" data-u-sharing="milestones" ${universe.sharing.milestones?'checked':''}>Show completed milestone titles in my local visitor preview</label><label class="u-check"><input type="checkbox" data-u-sharing="placements" ${universe.sharing.placements?'checked':''}>Show clearly labeled sample placements in my local visitor preview</label><p>Birth details, reflections, resonance answers and aspirations are never included. These controls demonstrate sharing; they do not publish a profile.</p></div><div class="u-visitor-preview"><span class="eyebrow">WHAT A VISITOR WOULD SEE · LOCAL ONLY</span><h3>${escapeHTML(worldState.name)}’s universe</h3>${universe.sharing.milestones?myMilestones().length?`<ul>${myMilestones().map(m=>`<li>✧ ${m.title}</li>`).join('')}</ul>`:'<p>No completed milestones to display yet.</p>':'<p>Your milestone activity is private.</p>'}${universe.sharing.placements?'<p>Sample Sun in Leo · Sample Moon in Pisces<br><small>Fictional chart, not this person’s calculated placements.</small></p>':''}${uButton('Copy my permitted milestone caption','id="u-copy-achievement"',true)}</div></section><section class="u-glass u-invitation"><span class="eyebrow">AN INVITATION YOU CONTROL</span><label>Editable invitation draft<textarea id="u-invite-text" maxlength="1000">I’m exploring Inner Orbit—a universe of self-discovery and small, meaningful growth practices. Would you like to explore it with me?</textarea></label>${uButton('Copy invitation draft','id="u-copy-invite"',true)}<p class="u-fine">Copy only. No friend request, message or invitation is sent. A live social network, public profiles and account-based invitations are not connected. Basic friendships and community are intended to remain free.</p></section>`,'bridge')}
function livingRelationships(){const f=friendSamples[universeSession.friend];return uPage(`${uHead('THE CONSTELLATION BRIDGE · RELATIONSHIP EXPLORER','Connection begins<br><em>with curiosity.</em>',`Explore a symbolic conversation between the sample Alex profile and fictional ${f.name}. This is not calculated compatibility for two real people.`)}<div class="u-relationship-art">${celestialObject('relationships','u-large-object')}<span>Alex · sample expression</span><span>${f.name} · sample ${f.path}</span></div><div class="u-toolbar" role="group" aria-label="Relationship perspective">${[['strengths','Shared strengths'],['differences','Different rhythms'],['practice','A conversation']].map(([k,t])=>`<button data-u-relationship="${k}" aria-pressed="${relationshipTab===k}">${t}</button>`).join('')}</div><section class="u-glass u-relationship-reading"><span class="eyebrow">NO SCORES. NO FIXED VERDICTS.</span><h2>${relationshipTab==='strengths'?'Let your perspectives expand each other.':relationshipTab==='differences'?'Different rhythms deserve room.':'Listen for the person behind the pattern.'}</h2><p>${relationshipTab==='strengths'?`Alex’s fictional expression theme and ${f.name}’s ${f.path} theme suggest a conversation between sharing an idea and ${f.path==='focus'?'giving it a useful structure':f.path==='connection'?'understanding how it affects others':'trying it in a different form'}.`:relationshipTab==='differences'?'One person may think aloud while another needs quiet time. Ask what each person needs rather than assuming a chart can tell you.':'Take turns completing: “Something I want you to understand about me is…” Reflect back what you heard before offering advice.'}</p><div class="u-question">${relationshipTab==='strengths'?'What do you notice that I might have missed?':relationshipTab==='differences'?'Would you like to talk now, or take time and return to this?':'What makes a conversation feel safe and honest to you?'}</div><div class="u-actions">${uRoute('Practice communication','journey','communication')}${uRoute('Return to friend galaxies','connections')}${uButton('Reflect on connection', 'data-u-theme="connection" data-u-panel="resonate"',true)}</div></section>`,'relationships')}
